    r = json.loads(opener.open(req, timeout=5).read().decode("utf-8"))
    print("[fs-master] ì—ì´ì „íŠ¸ ë“±ë¡: %s" % r.get("url", url))
except urllib.error.HTTPError as e:
    try:
        detail = json.loads(e.read().decode("utf-8")).get("detail", "")
