    local maddr="${myip:-<ë§ˆìŠ¤í„°IP>}$( [ "$PORT" = 15900 ] || echo ":$PORT")"
    echo "  ì—ì´ì „íŠ¸ ì¶”ê°€: ê° ì„œë²„(root)ì—ì„œ ì•„ëž˜ í•œ ì¤„ì´ë©´ ë§ˆìŠ¤í„°ì—ì„œ ì„¤ì¹˜ íŒŒì¼ì„ ë°›ì•„ ì„¤ì¹˜í•˜ê³  ìžë™ ë“±ë¡ë©ë‹ˆë‹¤."
    echo "      cd /tmp && curl -fsS -o fs-agent-m-install.sh http://$maddr/dl/fs-agent-m-install.sh && bash fs-agent-m-install.sh --master $maddr"
    echo "  ì—ì´ì „íŠ¸ ì—…ê·¸ë ˆì´ë“œ: ê° ì„œë²„(root)ì—ì„œ"
    echo "      cd /tmp && curl -fsS -o fs-agent-m-install.sh http://$maddr/dl/fs-agent-m-install.sh && bash fs-agent-m-install.sh"
    echo "  ë§ˆìŠ¤í„° â†” ì—ì´ì „íŠ¸ ì‚¬ì´ì— $PORT(ë§ˆìŠ¤í„°)Â·15892(ì—ì´ì „íŠ¸) í¬íŠ¸ê°€ ì—´ë ¤ ìžˆì–´ì•¼ í•©ë‹ˆë‹¤ (ë°©í™”ë²½ì€ ê±´ë“œë¦¬ì§€ ì•ŠìŒ)."
    echo "  ìƒíƒœ: systemctl status $SERVICE   ë¡œê·¸: journalctl -u $SERVICE"
    echo "  ìž¬ì‹œìž‘: systemctl restart $SERVICE   ì œê±°: sudo bash $0 --uninstall"
    echo "  ë¶€íŒ… ì‹œ ìžë™ ì‹œìž‘í•˜ì§€ ì•ŠìŠµë‹ˆë‹¤. ì„œë²„ ìž¬ë¶€íŒ… í›„ì—ëŠ” systemctl start $SERVICE ë¡œ ì‹œìž‘í•˜ì„¸ìš”."
  else
